std::string appendAndDelete(std::string s, std::string target, int k) {
    int i = 0;
    while (i < s.length() && i < target.length() && s[i] == target[i]) {
        i++;
    }
    int cost = s.length() + target.length() - 2 * i;
    if (cost <= k) {
        return s.substr(0, i) + target.substr(i);
    } else {
        return s;
    }
}

int main() {
    std::string s = "helloworld";
    std::string target = "world";
    int k = 2;
    std::cout << appendAndDelete(s, target, k) << std::endl;
    return 0;
}
