int bonAppetit(vector<int> b, int k, int cost, int n) {
    int totalCost = 0;
    for (int i = 0; i < n; i++) {
        totalCost += b[i];
    }
    int annaCost = totalCost - b[k];
    if (cost == annaCost) {
        return 0;
    } else {
        return cost - annaCost;
    }
}

