#include <algorithm>

int breakingRecords(std::vector<int> scores) {
    int max_score = scores[0];
    int min_score = scores[0];
    int max_count = 0;
    int min_count = 0;

    for (int i = 1; i < scores.size(); i++) {
        if (scores[i] > max_score) {
            max_score = scores[i];
            max_count += 1;
        } else if (scores[i] < min_score) {
            min_score = scores[i];
            min_count += 1;
        }
    }

    return max_count > min_count? max_count : min_count;
}

int main() {
    std::vector<int> scores = {10, 5, 20, 20, 4, 5, 2, 25, 1};
    std::cout << breakingRecords(scores) << std::endl;
    return 0;
}
