std::vector<int> circularArrayRotation(std::vector<int> a, int k) {
    int n = a.size();
    k = k % n;
    std::vector<int> b = a;
    for (int i = 0; i < k; i++) {
        int temp = b[0];
        for (int j = 0; j < n - 1; j++) {
            b[j] = b[j + 1];
        }
        b[n - 1] = temp;
    }
    return b;
}

int main() {
    std::vector<int> a = {1, 2, 3, 4, 5};
    int k = 2;
    std::vector<int> result = circularArrayRotation(a, k);
    for (int num : result) {
        std::cout << num << " ";
    }
    return 0;
}
